public sealed class NaturalContinuationTests {
 [Serializable]public sealed class FileProof {public string Path,Sha256;}
 [Serializable]public sealed class ArchiveRow {public string source,archive,sha256;public bool verified;}
 [Serializable]public sealed class ArchiveRows {public ArchiveRow[] rows;}
 [Serializable]public sealed class CheckpointProof {public string Batch,SourceDirectory,RunId,ContentVersion,FinalRootPath,FinalRootSha256,ReportPath,ReportSha256,BatchManifestPath,BatchManifestSha256;public FileProof[] Files;}
 private static string Hash(string p){using(var sha=SHA256.Create())using(var stream=File.OpenRead(p))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}
 private static string CloneCheckpoint(string proofPath,string destination,out CheckpointProof proof){
  proof=JsonUtility.FromJson<CheckpointProof>(File.ReadAllText(proofPath));Assert.That(proof.Batch,Is.Not.Null.And.Not.Empty);Assert.That(proof.RunId,Is.Not.Null.And.Not.Empty);
  Assert.That(Hash(proof.BatchManifestPath),Is.EqualTo(proof.BatchManifestSha256));
  Assert.That(new DirectoryInfo(Path.GetDirectoryName(proof.BatchManifestPath)).Name,Is.EqualTo(proof.Batch));
  var archive=JsonUtility.FromJson<ArchiveRows>("{\"rows\":"+File.ReadAllText(proof.BatchManifestPath)+"}").rows;
  foreach(var pair in new[]{new[]{proof.ReportPath,proof.ReportSha256},new[]{proof.FinalRootPath,proof.FinalRootSha256}})Assert.That(archive.Any(r=>r.verified&&r.sha256==pair[1]&&(Path.GetFullPath(r.archive)==Path.GetFullPath(pair[0])||Path.GetFullPath(r.source)==Path.GetFullPath(pair[0]))),Is.True,"Source evidence must belong to declared verified archive batch");
  Assert.That(Hash(proof.FinalRootPath),Is.EqualTo(proof.FinalRootSha256));Assert.That(Hash(proof.ReportPath),Is.EqualTo(proof.ReportSha256));
  Assert.That(File.ReadAllLines(proof.ReportPath).Contains("outcome=NaturalChampionD43"),Is.True,"Source batch must be a sealed natural D43 success");
  string root=Path.GetFullPath(proof.SourceDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
  var actual=Directory.GetFiles(root,"*",SearchOption.AllDirectories).Select(p=>p.Substring(root.Length).Replace('\\','/')).OrderBy(p=>p).ToArray();Assert.That(proof.Files.Select(f=>f.Path).OrderBy(p=>p).ToArray(),Is.EqualTo(actual),"Proof must list entire sealed save");Directory.CreateDirectory(destination);
  foreach(var f in proof.Files){string source=Path.GetFullPath(Path.Combine(root,f.Path));Assert.That(source.StartsWith(root,StringComparison.OrdinalIgnoreCase),Is.True);Assert.That(Hash(source),Is.EqualTo(f.Sha256));string output=Path.Combine(destination,f.Path);Directory.CreateDirectory(Path.GetDirectoryName(output));AutomationEvidence.Copy(source,output,false);Assert.That(Hash(output),Is.EqualTo(f.Sha256));}
  return Hash(proofPath);
 }
 private static T Read<T>(GameSession s,string owner)=>JsonUtility.FromJson<T>(s.InspectSnapshot().FindFragment(owner,"player").Json);
 private static string HistoryJson(AchievementHistoryEntry h)=>JsonUtility.ToJson(h.Snapshot)+"\n"+h.NoteState+"\n"+h.Note;
 private static string PermanentJson(GameSession s)=>s.InspectSnapshot().PermanentFragments.Single(f=>f.Owner=="progression"&&f.Scope=="permanent").Json;
 [Serializable] private sealed class WorldStamp { public int Day;public string Phase,BarrierId; }
 private static RootEnvelope ObserveFreeze(GameSession s,RootEnvelope ready,ref bool verified){
  var root=s.InspectSnapshot();if(root==null)return ready;var sf=root.FindFragment("session","player");if(sf==null)return ready;
  var state=JsonUtility.FromJson<SessionState>(sf.Json);if(state.Day!=84)return ready;
  var c=JsonUtility.FromJson<CompetitionState>(root.FindFragment("competition","player").Json);
  Assert.That(c.Current.Ordinal,Is.EqualTo(2));Assert.That(c.Current.ContestDay,Is.EqualTo(84));
  var wf=root.FindFragment("world","shared");var world=wf==null?null:JsonUtility.FromJson<WorldStamp>(wf.Json);
  if(c.Current.FrozenActors.Length==0&&world!=null&&world.Day==84&&world.Phase=="DayOpenReady"){
   foreach(string actor in new[]{"player","rival","beginner","veteran","coach"}){var actorState=JsonUtility.FromJson<SessionState>(root.FindFragment("session",actor).Json);Assert.That(actorState.Day,Is.EqualTo(84));Assert.That(actorState.Phase,Is.EqualTo("DayOpenReady"));}
   return JsonUtility.FromJson<RootEnvelope>(JsonUtility.ToJson(root));
  }
  if(!verified&&c.Current.FrozenActors.Length>0){Assert.That(ready,Is.Not.Null,"Missing observed pre-freeze committed barrier");Assert.That(c.Current.BarrierId,Is.EqualTo(JsonUtility.FromJson<WorldStamp>(ready.FindFragment("world","shared").Json).BarrierId));Assert.That(c.Current.FrozenActors.Select(x=>x.ActorId).OrderBy(x=>x).ToArray(),Is.EqualTo(new[]{"player","rival"}));foreach(var actor in c.Current.FrozenActors){var body=JsonUtility.FromJson<FitnessSimulator.Game.Body.BodyState>(ready.FindFragment("body",actor.ActorId).Json);Assert.That(actor.Day,Is.EqualTo(84));Assert.That(actor.Phase,Is.EqualTo("DayOpenReady"));Assert.That(actor.SourceCommitId,Is.EqualTo(ready.LastCommitId));Assert.That(actor.ActorRevision,Is.EqualTo(body.Revision));Assert.That(actor.SourceKind,Is.EqualTo(actor.ActorId=="player"?CompetitionSourceKind.PlayerProduction:CompetitionSourceKind.NpcProduction));Assert.That(root.FindFragment("body",actor.ActorId).Json,Is.EqualTo(ready.FindFragment("body",actor.ActorId).Json));Assert.That(JsonUtility.ToJson(actor.Body),Is.EqualTo(JsonUtility.ToJson(body)));}verified=true;}
  return ready;
 }
 [Test,Explicit("Requires sealed natural D43 proof and explicit long budget"),Timeout(3660000)]
 public void SealedD43ToD50AndD84ActualAttendance(){
  string input=Environment.GetEnvironmentVariable("FITNESS_CONTINUATION_PROOF");Assert.That(File.Exists(input),Is.True,"Missing sealed natural source proof");
  int seconds=int.Parse(Environment.GetEnvironmentVariable("FITNESS_CONTINUATION_SECONDS")??throw new InvalidOperationException("Explicit budget required"));Assert.That(seconds,Is.InRange(1,3600));
  string dir=Path.Combine(AutomationEvidence.OutputRoot,"Fitness-Continuation",Guid.NewGuid().ToString("N")),save=Path.Combine(dir,"save");AutomationEvidence.RegisterDirectory(dir);CheckpointProof proof;string proofHash=CloneCheckpoint(input,save,out proof);AutomationEvidence.Copy(input,Path.Combine(dir,"source-proof.json"));
  GameSession s=AutomationEvidenceSession.OpenAutomation(save,1);Assert.That(JsonUtility.ToJson(s.InspectSnapshot()),Is.EqualTo(JsonUtility.ToJson(JsonUtility.FromJson<RootEnvelope>(File.ReadAllText(proof.FinalRootPath)))),"Clone root must match sealed final root completely");AutomationEvidence.Copy(proof.FinalRootPath,Path.Combine(dir,"source-final.json"));AutomationEvidence.Copy(proof.ReportPath,Path.Combine(dir,"source-report.txt"));Assert.That(s.InspectSnapshot().RunId,Is.EqualTo(proof.RunId));Assert.That(s.InspectSnapshot().ContentVersion,Is.EqualTo(proof.ContentVersion));Assert.That(Read<SessionState>(s,"session").Day,Is.EqualTo(43));
  var initial=Read<CompetitionState>(s,"competition");Assert.That(initial.Current.Ordinal,Is.EqualTo(2));Assert.That(initial.Editions[0].Facts.Any(f=>f.Kind==CompetitionFactKind.Champion),Is.True,"Requires natural prior champion");
  var preservedHistory=new System.Collections.Generic.Dictionary<string,string>();s.Dispose();using(var historyStore=new LocalCheckpointStore(save,new UnityJsonStateCodec())){historyStore.Load();foreach(var h in new EndingProgression(new UnityJsonStateCodec()).ReadHistory(historyStore,0,64))preservedHistory.Add(h.Snapshot.AchievementId,HistoryJson(h));}s=AutomationEvidenceSession.OpenAutomation(save,1);var previous=JsonUtility.ToJson(initial.Editions[0]);string permanentBefore=PermanentJson(s);var progressionBefore=Read<ProgressionRun>(s,"progression");Assert.That(progressionBefore.TriggeredEndingIds.Count(x=>x=="bodybuilding_champion"),Is.EqualTo(1),"This continuation requires sealed prior bodybuilding champion");string[] triggeredBefore=progressionBefore.TriggeredEndingIds.ToArray();RootEnvelope freezeReady=null;bool freezeVerified=false,won=false,d85=false,terminal=false;string failedAchievement=null;string panelsAtD50=null;string operationPrefix="continuation/"+Guid.NewGuid().ToString("N")+"/";string initialBody=s.InspectSnapshot().FindFragment("body","rival").Json;int command=0,steps=0,inputEdges=0,clockCalls=0;bool enrolled=false,day50=false,attended=false,rest=false;string outcome="BudgetExhausted",error="";var timer=Stopwatch.StartNew();

  using(var trace=new EvidenceTrace(Path.Combine(dir,"trace.jsonl"))){
   Action<string> log=line=>{if(timer.Elapsed.TotalSeconds>seconds)throw new InvalidOperationException("WallBudgetExceeded");trace.WriteLine(line);};
   Action<FrontendOption> send=o=>{var v=s.ReadView();var a=new FrontendAction{OperationId=operationPrefix+(++command),RunId=v.RunId,ExpectedRevision=v.Revision,ActionId=o.Id,StringValue=o.StringValue,IntValue=o.IntValue};log(JsonUtility.ToJson(v));log(JsonUtility.ToJson(a));var r=AutomationEvidenceSession.Execute(s,a);log(JsonUtility.ToJson(r));Assert.That(r.Accepted,Is.True,r.Message);if(o.Id=="competition-attend"||o.Id=="competition-enroll"||o.Id=="ending-empty"){string committed=JsonUtility.ToJson(s.InspectSnapshot());var retry=AutomationEvidenceSession.Execute(s,a);log(JsonUtility.ToJson(retry));Assert.That(retry.Accepted,Is.True);Assert.That(JsonUtility.ToJson(s.InspectSnapshot()),Is.EqualTo(committed));}};
   try{for(;steps<500000&&timer.Elapsed.TotalSeconds<seconds;steps++){
    freezeReady=ObserveFreeze(s,freezeReady,ref freezeVerified);var v=s.ReadView();log(JsonUtility.ToJson(v));Assert.That(v.ScreenId,Is.Not.EqualTo("error"),v.Body);var opts=v.Actions.Where(a=>a.Enabled).ToArray();
    if(v.TrainingInput!=null){Assert.That(PublicEightInputDriver.DriveActiveSet(s,v.TrainingInput.ExerciseId,line=>{if(line.StartsWith("advance-ms="))clockCalls++;if(line.Contains("\"ActionId\":\"training-input\""))inputEdges++;log(line);}),Is.EqualTo("AwaitProductionResult"));continue;}
    var dayMatch=System.Text.RegularExpressions.Regex.Match(v.Status??"",@"第\s*(\d+)\s*日");int day=dayMatch.Success?int.Parse(dayMatch.Groups[1].Value):0;Assert.That(day,Is.LessThanOrEqualTo(85));FrontendOption o=null;
    if(v.ScreenId.StartsWith("summary/"))rest=false;
    if(attended&&day==85&&Read<CompetitionState>(s,"competition").Current.Ordinal==3){Assert.That(won,Is.True);var current=Read<CompetitionState>(s,"competition");Assert.That(current.Current.Ordinal,Is.EqualTo(3));Assert.That(current.Current.ContestDay,Is.EqualTo(126));Assert.That(Read<ProgressionRun>(s,"progression").TriggeredEndingIds,Is.EqualTo(triggeredBefore));Assert.That(PermanentJson(s),Is.EqualTo(permanentBefore));d85=true;outcome="D84ChampionContinuedD85";break;}
    if(attended&&v.ScreenId=="ending-menu"&&!opts.Any(a=>a.Id=="ending-continue")){var pr=Read<ProgressionRun>(s,"progression");Assert.That(won,Is.False);Assert.That(pr.TerminalLock,Is.True);Assert.That(pr.Active.EndingId,Is.EqualTo("competition_failed"));Assert.That(pr.Active.NoteState,Is.EqualTo(AchievementNoteState.CommittedEmpty));failedAchievement=pr.Active.AchievementId;terminal=true;outcome="D84NonChampionTerminal";break;}
    if(attended&&opts.Any(a=>a.Id=="ending-continue"))Assert.Fail("Repeated successful ending must not present or grant again");
    if(!enrolled&&day>=50&&opts.Any(a=>a.Id=="competition-menu"))o=opts.First(a=>a.Id=="competition-menu");
    if(v.ScreenId=="competition"){o=opts.FirstOrDefault(a=>a.Id=="competition-enroll"&&a.IntValue==0)??opts.FirstOrDefault(a=>a.Id=="competition-attend"&&a.IntValue==0)??opts.FirstOrDefault(a=>a.Id=="competition-close");}
    if(o==null&&opts.Any(a=>a.Id=="begin-set")){if(rest){o=opts.First(a=>a.Id=="rest"&&a.IntValue==180);send(o);rest=false;continue;}o=opts.FirstOrDefault(a=>a.Id=="begin-set"&&a.StringValue=="auto")??opts.First(a=>a.Id=="begin-set"&&a.StringValue=="manual"&&a.IntValue==0);}
    if(o==null&&opts.Any(a=>a.Id=="choose-entry"))o=opts.FirstOrDefault(a=>a.Id=="choose-entry"&&a.StringValue=="training-choice")??opts.First(a=>a.Id=="choose-entry");
    if(o==null&&opts.Any(a=>a.Id=="meal"))o=opts.FirstOrDefault(a=>a.Id=="meal"&&new[]{"porridge_egg","home_rice","home_noodles"}.Contains(a.StringValue));
    foreach(string id in new[]{"continue-game","ending-segment","ending-empty","settle","continue","shop-leave","item-use","competition-next","next-day"})if(o==null)o=opts.FirstOrDefault(a=>a.Id==id);
    if(o!=null){send(o);if(o.Id=="settle")rest=true;if(o.Id=="competition-enroll"){enrolled=true;var state=Read<CompetitionState>(s,"competition");Assert.That(day,Is.EqualTo(50));Assert.That(state.Current.Opened,Is.True);Assert.That(state.Current.Contest(ContestKind.Bodybuilding).Enrolled,Is.True);Assert.That(state.Current.Ordinal,Is.EqualTo(2));Assert.That(state.Current.ContestDay,Is.EqualTo(84));Assert.That(state.Current.RevealedJudges,Is.Zero);Assert.That(state.Current.RegistrationClosed,Is.False);Assert.That(state.Current.FrozenActors,Is.Empty);Assert.That(state.Current.Facts,Is.Empty);Assert.That(state.Current.ActualAttendanceCount,Is.Zero);Assert.That(state.Current.Contest(ContestKind.ThinBuild).Enrolled,Is.False);Assert.That(state.Current.Contests.All(c=>c.Results.Length==0&&c.JudgeIds.Length==3&&c.JudgeIds.Distinct().Count()==3),Is.True);Assert.That(CompetitionQueries.Entries(state,50).All(c=>c.Judges.All(j=>!j.Revealed&&j.Name==""&&j.Description=="")),Is.True);Assert.That(JsonUtility.ToJson(state.Editions[0]),Is.EqualTo(previous));panelsAtD50=string.Join("|",state.Current.Contests.Select(c=>string.Join(",",c.JudgeIds)));day50=true;}
     if(o.Id=="competition-attend"){var state=Read<CompetitionState>(s,"competition");Assert.That(day,Is.EqualTo(84));Assert.That(state.Current.ActualAttendanceCount,Is.EqualTo(1));Assert.That(JsonUtility.ToJson(state.Editions[0]),Is.EqualTo(previous));Assert.That(s.InspectSnapshot().FindFragment("body","rival").Json,Is.Not.EqualTo(initialBody));var result=state.Current.Contest(ContestKind.Bodybuilding).Results.Single().Score;attended=true;log(JsonUtility.ToJson(state));Assert.That(freezeVerified,Is.True);Assert.That(string.Join("|",state.Current.Contests.Select(c=>string.Join(",",c.JudgeIds))),Is.EqualTo(panelsAtD50));NaturalChampionRouteTests.AuditScores(s,ContestKind.Bodybuilding,false);won=result.Participants.Single(p=>p.ActorId==state.PlayerId).Rank==1;Assert.That(state.Current.Facts.Count(f=>f.Kind==(won?CompetitionFactKind.Champion:CompetitionFactKind.NonChampion)),Is.EqualTo(1));outcome=won?"D84ChampionActualAttendance":"D84NonChampionActualAttendance";}}
    else{var unknown=opts.FirstOrDefault(a=>!new[]{"save-plan","open-menu","competition-menu"}.Contains(a.Id));Assert.That(unknown,Is.Null,"MissingHandler: "+v.ScreenId+"/"+unknown?.Id);clockCalls++;log("advance-ms=0");s.Advance(0);}
   }Assert.That(day50&&attended&&freezeVerified&&(d85||terminal),Is.True,"CoverageMissing: D50/D84 freeze/settlement/aftermath not reached");Assert.That(JsonUtility.ToJson(Read<CompetitionState>(s,"competition").Editions[0]),Is.EqualTo(previous));Assert.That(PermanentJson(s),Is.EqualTo(permanentBefore));string complete=JsonUtility.ToJson(s.InspectSnapshot());s.Dispose();using(var historyStore=new LocalCheckpointStore(save,new UnityJsonStateCodec())){historyStore.Load();var all=new EndingProgression(new UnityJsonStateCodec()).ReadHistory(historyStore,0,64);Assert.That(all.Select(h=>h.Snapshot.AchievementId).Distinct().Count(),Is.EqualTo(all.Count));foreach(var entry in preservedHistory)Assert.That(HistoryJson(all.Single(h=>h.Snapshot.AchievementId==entry.Key)),Is.EqualTo(entry.Value));Assert.That(all.Count(h=>h.Snapshot.EndingId=="bodybuilding_champion"&&h.Snapshot.RunId==proof.RunId),Is.EqualTo(1));if(won)Assert.That(all.Count,Is.EqualTo(preservedHistory.Count));else{Assert.That(all.Count,Is.EqualTo(preservedHistory.Count+1));var failure=all.Single(h=>h.Snapshot.AchievementId==failedAchievement);Assert.That(failure.Snapshot.EndingId,Is.EqualTo("competition_failed"));Assert.That(failure.Snapshot.Terminal,Is.True);Assert.That(failure.Snapshot.Day,Is.EqualTo(84));Assert.That(failure.NoteState,Is.EqualTo(AchievementNoteState.CommittedEmpty));Assert.That(failure.Note,Is.EqualTo(""));}}s=AutomationEvidenceSession.OpenAutomation(save,1);Assert.That(JsonUtility.ToJson(s.InspectSnapshot()),Is.EqualTo(complete));if(terminal){Assert.That(Read<ProgressionRun>(s,"progression").TerminalLock,Is.True);Assert.That(s.ReadView().Actions.Any(a=>a.Enabled&&a.Id=="ending-continue"),Is.False);}}
   catch(Exception ex){error=ex.ToString();throw;}
   finally{trace.Flush();AutomationEvidence.WriteAllText(Path.Combine(dir,"final.json"),JsonUtility.ToJson(s.InspectSnapshot(),true));AutomationEvidence.WriteAllText(Path.Combine(dir,"report.txt"),"sourceBatch="+proof.Batch+"\nsourceReportSha256="+proof.ReportSha256+"\nsourceFinalSha256="+proof.FinalRootSha256+"\noperationPrefix="+operationPrefix+"\nproofSha256="+proofHash+"\nrunId="+proof.RunId+"\ncurrentGameAssemblySha256="+Hash(typeof(GameSession).Assembly.Location)+"\nmaxDay=85\nmaxSeconds="+seconds+"\nevidenceBytes="+trace.Bytes+"\nevidenceByteLimit="+AutomationEvidence.TraceLimit+"\nsteps="+steps+"\nbusinessCommands="+command+"\ninputEdges="+inputEdges+"\nclockCalls="+clockCalls+"\nD50="+day50+"\nfreezeVerified="+freezeVerified+"\nD85="+d85+"\nterminal="+terminal+"\nD84Attendance="+attended+"\noutcome="+outcome+"\nexception="+error);s.Dispose();TestContext.WriteLine(dir);}
  }
 }
}
